<template>
  <div class="control" :class="{ 'has-icons-right': postfix, 'has-prefix': prefix, 'is-expanded': isExpanded }">
    <span v-if="prefix" class="button prefix" :class="{ 'is-danger': hasError }" @click="$emit('click-prefix')">
      <span>
        {{ $filters.uppercaseFirstLetter(prefix) }}
      </span>
    </span>

    <div v-if="options" class="select" :class="{ 'is-danger': hasError }">
      <select v-model="value_" :disabled="disabled">
        <option v-if="!required" />
        <option v-for="option of options" :key="option" :value="option">
          {{ i18n ? $gettext(option, i18nContext) : option }}
        </option>
      </select>
    </div>

    <input
      v-else
      :type="type"
      :min="divisor ? min / divisor : min"
      :max="divisor ? Number(max) / divisor : max"
      :disabled="disabled"
      :placeholder="placeholder"
      v-model.lazy="value_"
      class="input"
      :class="{ 'is-danger': hasError }"
    />

    <span v-if="postfix" class="icon is-right">
      {{ postfix }}
    </span>
  </div>
</template>

<script setup lang="ts">
import type { PropType } from 'vue';

import { baseInputProps, useInputValue } from './input-value';

const props = defineProps({
  ...baseInputProps,
  min: {
    type: Number,
    default: null,
  },
  max: {
    type: [Number, String], // string is for date
    default: null,
  },
  modelValue: {
    type: [String, Number, Boolean],
    default: null,
  },
  prefix: {
    type: String,
    default: null,
  },
  postfix: {
    type: String,
    default: null,
  },
  options: {
    type: Array as PropType<string[]>,
    default: null,
  },
  isExpanded: {
    type: Boolean,
    default: null,
  },
  disabled: {
    type: Boolean,
    default: false,
  },
  i18n: {
    type: Boolean,
    default: false,
  },
  i18nContext: {
    type: String,
    default: undefined,
  },
});
const emit = defineEmits(['update:modelValue', 'click-prefix']);

const { value_ } = useInputValue(props, emit);
</script>

<style scoped>
select,
input {
  min-width: 15rem;
}

.select,
select {
  width: 100%;
}

.has-prefix {
  display: flex;

  .prefix {
    cursor: default;
    background-color: whitesmoke;
    border-color: var(--c2c-grey-lighter);
    color: var(--c2c-grey);
    box-shadow: none;

    margin-right: -1px;
    border-bottom-right-radius: 0;
    border-top-right-radius: 0;
  }
  input,
  select {
    border-bottom-left-radius: 0;
    border-top-left-radius: 0;
  }
}

.prefix.is-danger {
  border-color: var(--c2c-danger);
}
</style>
